function drawHeart(x, y, radius) {
  if (radius < 1) return;

  push();
  stroke(255, 0, 0); // red
  translate(x, y, 0);

  // pythagorean-like heart
  beginShape(QUADS);
  vertex(-radius, -radius*0.3, 0);
  vertex(radius, -radius*0.3, 0);
  vertex(radius, radius*0.3, 0);
  vertex(-radius, radius*0.3, 0);
  endShape();

  // recursively draw smaller hearts
